import{_ as e,o as s,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Ceph Orchestrator 2023-01-24","description":"","frontmatter":{"title":"Ceph Orchestrator 2023-01-24","date":"2023-01-24T00:00:00.000Z","updated":"2023-01-26T00:00:00.000Z","tags":["Ceph","Distributed Storage","Systemd","iSCSI","SSH"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_2023-01-24.md","filePath":"posts/2023/Ceph_Orchestrator_2023-01-24.md","lastUpdated":1780460162000}'),a={name:"posts/2023/Ceph_Orchestrator_2023-01-24.md"};function p(n,t,i,_,c,d){return s(),r("div",null,[...t[0]||(t[0]=[o("<p>在2023年1月24日的Ceph Orchestrator会议中，主要讨论了以下议题：</p><ol><li><p><strong>systemd服务启动超时问题</strong>：由于systemd服务启动超时，容器进程不会被终止，导致服务处于失败状态但进程仍在运行。解决方案是通过PR修改，确保在服务启动失败时执行post-stop操作，以正确终止容器进程。该PR已通过测试并被接受，计划合并到主分支。</p></li><li><p><strong>iSCSI问题与host.containers.internal条目</strong>：host.containers.internal条目导致iSCSI问题。临时解决方案是通过挂载主机版本的seos来解决问题，但需要进一步研究和测试。计划进行更多实验和讨论，以确定最佳长期解决方案。</p></li><li><p><strong>SSH密钥验证问题</strong>：当前存在SSH密钥验证不足的问题，可能导致错误密钥被接受。建议使用现有库进行密钥验证，并更新相关文档。已检查并更新文档，确保用户使用正确的密钥设置方法。</p></li></ol><p>会议还讨论了关于容器网络设置和podman的潜在问题，但未形成具体决议。</p><p>会议决定事项包括：合并systemd服务启动超时问题的PR；临时使用挂载主机seos的解决方案，同时进行更多研究和测试以确定长期解决方案；更新SSH密钥设置的文档，确保用户使用正确的验证方法。</p><p>后续行动计划包括完成systemd服务启动超时问题PR的合并、进行更多实验和测试以确定host.containers.internal条目的最佳解决方案，以及更新并验证SSH密钥设置的文档。</p>",5)])])}const h=e(a,[["render",p]]);export{S as __pageData,h as default};
